@page "/apply"
@rendermode InteractiveServer
@using sv_318447a3d8a04a25b697be8af161785d.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    @* ── Step Indicator Bar ── *@
    <nav class="step-bar">
        @for (int i = 0; i < StepLabels.Length; i++)
        {
            var stepIndex = i;
            var css = stepIndex == _currentStep ? "step active"
                    : stepIndex < _currentStep ? "step completed"
                    : "step future";

            <button class="@css"
                    disabled="@(stepIndex >= _currentStep)"
                    @onclick="() => GoToStep(stepIndex)">
                <span class="step-number">
                    @if (stepIndex < _currentStep)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepLabels[stepIndex]</span>
            </button>
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger mt-3">@_errorMessage</div>
    }

    @* ── Step 1: Personal Info ── *@
    @if (_currentStep == 0)
    {
        <section class="step-content">
            <h2>Personal Information</h2>

            <div class="mb-3">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_fullName" placeholder="Jane Doe" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="_email" placeholder="jane@example.com" />
            </div>
            <div class="mb-3">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="_phone" placeholder="(555) 123-4567" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_address" placeholder="123 Main St, City, State" />
            </div>

            <div class="step-buttons">
                <span></span>
                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                    @if (_isValidating) { <span>Validating…</span> } else { <span>Next &rarr;</span> }
                </button>
            </div>
        </section>
    }

    @* ── Step 2: Work History ── *@
    @if (_currentStep == 1)
    {
        <section class="step-content">
            <h2>Work History</h2>

            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var idx = i;
                var entry = _workEntries[idx];

                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Position @(idx + 1)</h5>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                            }
                        </div>

                        <div class="row">
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Company <span class="text-danger">*</span></label>
                                <input class="form-control" @bind="entry.Company" />
                            </div>
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                <input class="form-control" @bind="entry.Title" />
                            </div>
                        </div>
                        <div class="row">
                            <div class="col-md-4 mb-3">
                                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                <input type="date" class="form-control" @bind="entry.StartDate" />
                            </div>
                            <div class="col-md-4 mb-3">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                            </div>
                            <div class="col-md-4 mb-3 d-flex align-items-end">
                                <div class="form-check">
                                    <input type="checkbox" class="form-check-input" id="current-@idx" @bind="entry.IsCurrent" />
                                    <label class="form-check-label" for="current-@idx">Currently working here</label>
                                </div>
                            </div>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" rows="3" @bind="entry.Description"></textarea>
                        </div>
                    </div>
                </div>
            }

            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>

            <div class="step-buttons">
                <button class="btn btn-secondary" @onclick="PreviousStep">&larr; Back</button>
                <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next &rarr;</button>
            </div>
        </section>
    }

    @* ── Step 3: References ── *@
    @if (_currentStep == 2)
    {
        <section class="step-content">
            <h2>References</h2>

            @for (int i = 0; i < _references.Count; i++)
            {
                var idx = i;
                var reference = _references[idx];

                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Reference @(idx + 1)</h5>
                            @if (_references.Count > 2)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(idx)">Remove</button>
                            }
                        </div>

                        <div class="row">
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Name <span class="text-danger">*</span></label>
                                <input class="form-control" @bind="reference.Name" />
                            </div>
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                <input class="form-control" @bind="reference.Relationship" placeholder="e.g., Former Manager" />
                            </div>
                        </div>
                        <div class="row">
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Email <span class="text-danger">*</span></label>
                                <input type="email" class="form-control" @bind="reference.Email" />
                            </div>
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Phone <span class="text-danger">*</span></label>
                                <input type="tel" class="form-control" @bind="reference.Phone" />
                            </div>
                        </div>
                    </div>
                </div>
            }

            @if (_references.Count < 3)
            {
                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
            }

            <div class="step-buttons">
                <button class="btn btn-secondary" @onclick="PreviousStep">&larr; Back</button>
                <button class="btn btn-primary" @onclick="NextFromReferences">Next &rarr;</button>
            </div>
        </section>
    }

    @* ── Step 4: Cover Letter ── *@
    @if (_currentStep == 3)
    {
        <section class="step-content">
            <h2>Cover Letter</h2>

            <div class="mb-2">
                <textarea class="form-control" rows="12" maxlength="2000"
                          @bind="_coverLetter" @bind:event="oninput"
                          placeholder="Write your cover letter here…"></textarea>
            </div>
            <div class="text-muted mb-3">@(_coverLetter?.Length ?? 0) / 2000 characters</div>

            <div class="step-buttons">
                <button class="btn btn-secondary" @onclick="PreviousStep">&larr; Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next &rarr;</button>
            </div>
        </section>
    }

    @* ── Step 5: Review & Submit ── *@
    @if (_currentStep == 4)
    {
        <section class="step-content">
            <h2>Review &amp; Submit</h2>

            @if (_isSubmitted)
            {
                <div class="alert alert-success">
                    <h4>Application Submitted!</h4>
                    <p>Your application has been received. Your confirmation number is <strong>#@_applicationId</strong>.</p>
                </div>
            }
            else
            {
                @* Personal Info *@
                <div class="review-section">
                    <div class="review-header">
                        <h4>Personal Information</h4>
                        <button class="btn btn-link btn-sm" @onclick="() => GoToStep(0)">Edit</button>
                    </div>
                    <dl class="row mb-0">
                        <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@_fullName</dd>
                        <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                        <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                        <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                    </dl>
                </div>

                @* Work History *@
                <div class="review-section">
                    <div class="review-header">
                        <h4>Work History</h4>
                        <button class="btn btn-link btn-sm" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
