toolArgs.file_text:
.apply-container {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* ── Step Bar ── */
.step-bar {
    display: flex;
    justify-content: space-between;
    margin-bottom: 1.5rem;
    padding: 0;
    gap: 0.25rem;
}

.step-bar .step {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    padding: 0.75rem 0.25rem;
    background: none;
    border: none;
    border-bottom: 3px solid #dee2e6;
    cursor: default;
    transition: border-color 0.2s, opacity 0.2s;
}

.step-bar .step.completed {
    border-bottom-color: #198754;
    cursor: pointer;
}

.step-bar .step.active {
    border-bottom-color: #0d6efd;
}

.step-bar .step.future {
    opacity: 0.45;
}

.step-number {
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.85rem;
    background: #e9ecef;
    color: #495057;
}

.step.active .step-number {
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-number {
    background: #198754;
    color: #fff;
}

.step-label {
    font-size: 0.78rem;
    text-align: center;
    line-height: 1.2;
}

/* ── Step Content ── */
.step-content {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
}

/* ── Review Section ── */
.review-section {
    border: 1px solid #e9ecef;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.review-header h4 {
    margin-bottom: 0;
    font-size: 1.1rem;
}

